theorem davenportConstant_le {n : ℕ∞}
    (h : ∀ {S : Multiset G}, S.IsMinimalZeroSum → (S.card : ℕ∞) ≤ n) :
    davenportConstant G ≤ n

theorem davenportConstant_le_of_forall_exists_isZeroSum {n : ℕ}
    (h : ∀ S : Multiset G, n ≤ S.card → ∃ T ≤ S, T ≠ 0 ∧ T.IsZeroSum) :
    davenportConstant G ≤ n

private theorem exists_le_map_eq_of_le_map {α β : Type*} [Nonempty α] {f : α → β}
    (hf : Function.Injective f) {s : Multiset α} {t : Multiset β} (h : t ≤ s.map f) :
    ∃ u ≤ s, u.map f = t

@[simp]
theorem factorizationLengths_of_irreducible (ha : Irreducible a) :
    factorizationLengths a = {1}

theorem add_mem_factorizations_mul {f g : Associates.Factorization α}
    (hf : f ∈ factorizations a) (hg : g ∈ factorizations b) :
    f + g ∈ factorizations (a * b)

@[simp]
theorem UniqueFactorizationMonoid.factorizationLengths_eq_singleton (ha : a ≠ 0) :
    factorizationLengths a = {(UniqueFactorizationMonoid.factors a).card}

private theorem card_prod (f : Multiset (BlockMonoidOver G₀))
    (hf : ∀ a ∈ f, a ≠ 0) :
    card f.prod = (f.map card).sum

private theorem factorization_card_le (S : blockMonoidOver G₀)
    {f : Associates.Factorization (BlockMonoidOver G₀)}
    (hf : f ∈ factorizations (of S)) : f.card ≤ (S : Multiset G).card

private theorem atomSequence_le_of_mem_factorization (S : blockMonoidOver G₀)
    {p : {p : Associates (BlockMonoidOver G₀) // Irreducible p}}
    {f : Associates.Factorization (BlockMonoidOver G₀)}
    (hf : f ∈ factorizations (of S)) (hp : p ∈ f) :
    (atomSequence p : Multiset G) ≤ (S : Multiset G)

private theorem weight_of (S : blockMonoid G) :
    weight (BlockMonoidOver.of S) =
      (S : Multiset G).card + (S : Multiset G).count 0

private theorem irreducible_weight_bounds [Nontrivial G] {d : ℕ}
    (hD : (d : ℕ∞) = davenportConstant G) {a : BlockMonoid G}
    (ha : Irreducible a) : 2 ≤ weight a ∧ weight a ≤ d

private theorem factorization_weight_bounds [Nontrivial G] {d : ℕ}
    (hD : (d : ℕ∞) = davenportConstant G) (S : blockMonoid G)
    {f : Associates.Factorization (BlockMonoid G)}
    (hf : f ∈ factorizations (BlockMonoidOver.of S)) :
    2 * f.card ≤ (S : Multiset G).card + (S : Multiset G).count 0 ∧
      (S : Multiset G).card + (S : Multiset G).count 0 ≤ d * f.card

private theorem elasticity_le_davenport_div_two [Nontrivial G] {d : ℕ}
    (hD : (d : ℕ∞) = davenportConstant G) {a : BlockMonoid G}
    (ha : a ≠ 0) (hnu : ¬IsUnit a) :
    _root_.elasticity a ≤ (d : ℝ≥0∞) / 2

private theorem negBlock_minimal {S : blockMonoid G}
    (hS : (S : Multiset G).IsMinimalZeroSum) :
    ((negBlock S : blockMonoid G) : Multiset G).IsMinimalZeroSum

private theorem prod_pairBlocks (S : Multiset G) :
    (S.map fun g ↦ BlockMonoidOver.of (pairBlock g)).prod =
      BlockMonoidOver.of (symmBlock S)

private lemma minimalZeroSum_subset_pair {g : G} (hg : g + g = 0) {S : Multiset G}
    (hS : S.IsMinimalZeroSum) (hSupp : ∀ x ∈ S, x ∈ ({0, g} : Set G)) :
    S = {0} ∨ (S = {g, g} ∧ g ≠ 0)

private lemma pairWeight_of {g : G} (S : blockMonoidOver ({0, g} : Set G)) :
    pairWeight (BlockMonoidOver.of S) =
      2 * (S : Multiset G).count 0 + (S : Multiset G).count g

private lemma pairWeight_irreducible {g : G} (hg : g + g = 0)
    {a : BlockMonoidOver ({0, g} : Set G)} (ha : Irreducible a) :
    pairWeight a = if g = 0 then 3 else 2

private lemma pair_length_weight {g : G} (hg : g + g = 0)
    {a : BlockMonoidOver ({0, g} : Set G)} {k : ℕ}
    (hk : k ∈ factorizationLengths a) :
    k * (if g = 0 then 3 else 2) = pairWeight a

private theorem associated_of_divisorMultiset_eq (D : DivisorTheory α P)
    {a b : α} (ha : a ≠ 0) (hb : b ≠ 0)
    (hab : D.divisorMultiset a = D.divisorMultiset b) : Associated a b

private theorem divisorMultiset_prod (D : DivisorTheory α P) (f : Multiset α)
    (hf : f.prod ≠ 0) :
    D.divisorMultiset f.prod = (f.map D.divisorMultiset).sum

private theorem card_le_card_sum_divisorMultiset (D : DivisorTheory α P)
    (g : Multiset α) (hgI : ∀ b ∈ g, Irreducible b) :
    g.card ≤ ((g.map D.divisorMultiset).sum).card

private theorem factorization_card_le (D : DivisorTheory α P) {a : α} (ha : a ≠ 0)
    {f : Associates.Factorization α} (hf : f ∈ factorizations a) :
    f.card ≤ (D.divisorMultiset a).card

private theorem atomDivisor_le_of_mem_factorization (D : DivisorTheory α P)
    {a : α} (ha : a ≠ 0) {p : {p : Associates α // Irreducible p}}
    {f : Associates.Factorization α} (hf : f ∈ factorizations a) (hp : p ∈ f) :
    atomDivisor D p ≤ D.divisorMultiset a

theorem mem_principalDivisors_of_eq {φ : α →*₀ DivisorMonoid P}
    {d : FreeDivisorMonoid P} {a : α} (h : φ a = (d : DivisorMonoid P)) :
    FreeDivisorMonoid.toDivisorGroup P d ∈ principalDivisors φ

private theorem dvd_iff_divisorMultiset_le (D : DivisorTheory α P)
    {a b : α} (ha : a ≠ 0) (hb : b ≠ 0) :
    a ∣ b ↔ D.divisorMultiset a ≤ D.divisorMultiset b
